<script setup lang="ts">import Dialog from 'primevue/dialog';import {useAcademyDonations,type AcademyDonation} from '~/composables/useAcademyDonations';definePageMeta({layout:'main',middleware:['auth','plearnd-admin']});const {adminList,adminApprove,adminReject}=useAcademyDonations();const rows=ref<AcademyDonation[]>([]),meta=ref<any>({}),loading=ref(true),selected=ref<AcademyDonation|null>(null),show=ref(false),reason=ref('');const load=async(p=1)=>{loading.value=true;try{const r=await adminList({page:p});rows.value=r.data;meta.value=r.meta}finally{loading.value=false}};onMounted(()=>load());const approve=async(r:AcademyDonation)=>{await adminApprove(r.id);await load(meta.value.current_page||1)};const reject=async()=>{if(selected.value&&reason.value.trim()){await adminReject(selected.value.id,reason.value);show.value=false;reason.value='';await load(meta.value.current_page||1)}};const amount=(r:AcademyDonation)=>r.donation_type==='point'?`${r.points_amount} points`:`${r.cash_amount} ${r.currency||'THB'}`</script>
<template><div class="mx-auto max-w-7xl space-y-6 p-6"><h1 class="text-2xl font-bold">Academy donation queue</h1><div class="overflow-hidden rounded-2xl bg-white shadow"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-4">ID</th><th class="p-4">Academy</th><th class="p-4">Donor</th><th class="p-4">Amount</th><th class="p-4">Status</th><th class="p-4">Slip</th><th class="p-4">Actions</th></tr></thead><tbody><tr v-if="loading"><td colspan="7" class="p-8 text-center">Loading…</td></tr><tr v-for="r in rows" :key="r.id" class="border-t"><td class="p-4">{{r.id}}</td><td class="p-4">{{r.academy?.name||r.academy_id}}</td><td class="p-4">{{r.donor_display_name||'Anonymous'}}</td><td class="p-4">{{amount(r)}}</td><td class="p-4">{{r.status}}</td><td class="p-4"><a v-if="r.slip_url" :href="r.slip_url" target="_blank" class="text-primary-600">Preview</a>—</td><td class="space-x-2 p-4"><button v-if="r.status==='pending'" class="min-h-[44px] sm:min-h-0 rounded bg-emerald-600 px-3 py-1 text-white" @click="approve(r)">Approve</button><button v-if="r.status==='pending'" class="min-h-[44px] sm:min-h-0 rounded bg-red-600 px-3 py-1 text-white" @click="selected=r;show=true">Reject</button></td></tr></tbody></table></div><Dialog v-model:visible="show" modal header="Reject donation" class="w-full max-w-md"><textarea v-model="reason" class="w-full rounded border p-3"/><button class="mt-3 w-full rounded bg-red-600 p-3 text-white" @click="reject">Reject</button></Dialog></div></template>
